async function load(){try{const [sr,cr]=await Promise.all([fetch('samples.json'),fetch('comparison.json')]);if(!sr.ok||!cr.ok)throw Error('Could not load the study files.');const samples=await sr.json(),c=await cr.json();const host=document.querySelector('#samples');host.replaceChildren();for(const s of samples.filter(s=>s.id!=='polaroid')){const a=document.createElement('article');a.className='sample';const label=document.createElement('div');label.className='eyebrow';label.textContent=s.title;const quote=document.createElement('blockquote');quote.textContent=s.text;if(s.id==='chinese-fragment')quote.lang='zh';const source=document.createElement('p');source.className='note';source.textContent=`Source PDF, page ${s.page}. ${s.why}`;a.append(label,quote,source);host.append(a)}const source=document.querySelector('#source');const h=document.createElement('h3');h.textContent='The source excerpt';const q=document.createElement('blockquote');q.textContent=c.source_excerpt.text;source.append(h,q);document.querySelector('#default').textContent=c.default.intro+'\n\n'+c.default.excerpt;document.querySelector('#poetry').textContent=c.poetry.excerpt}catch(e){document.querySelector('#samples').textContent='The excerpts could not load. Please refresh this page. '+e.message}}load();
